const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const hotan = ee.Geometry.Point([79.9, 37.1]).buffer(50000); // 50km buffer around Hotan
  const earlyStart = '2020-02-20';
  const earlyEnd = '2020-02-26';
  const lateStart = '2020-04-26';
  const lateEnd = '2020-05-02';

  // 2. Data Acquisition - Sentinel-2
  function getS2Collection(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(hotan)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
  }

  // Cloud masking function
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // NDVI calculation
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Get collections
  const earlyCol = getS2Collection(earlyStart, earlyEnd).map(maskS2clouds).map(addNDVI);
  const lateCol = getS2Collection(lateStart, lateEnd).map(maskS2clouds).map(addNDVI);

  // Check collection sizes
  const earlySize = earlyCol.size().getInfo();
  const lateSize = lateCol.size().getInfo();

  console.log(`Early period images: ${earlySize}`);
  console.log(`Late period images: ${lateSize}`);

  if (earlySize === 0 || lateSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create composites and calculate mean NDVI
  const earlyComposite = earlyCol.median().select('NDVI');
  const lateComposite = lateCol.median().select('NDVI');

  // Check valid pixels
  const earlyCount = earlyComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hotan,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const lateCount = lateComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hotan,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Early valid pixels: ${earlyCount}`);
  console.log(`Late valid pixels: ${lateCount}`);

  if (earlyCount === 0 || lateCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean NDVI
  const earlyNDVI = earlyComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hotan,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const lateNDVI = lateComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hotan,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Early NDVI: ${earlyNDVI ? earlyNDVI.toFixed(4) : 'null'}`);
  console.log(`Late NDVI: ${lateNDVI ? lateNDVI.toFixed(4) : 'null'}`);

  // Validation & Final Answer
  if (earlyNDVI === null || lateNDVI === null || 
      isNaN(earlyNDVI) || isNaN(lateNDVI) ||
      earlyNDVI > 1 || lateNDVI > 1 || 
      earlyNDVI < -1 || lateNDVI < -1) {
    console.log("<answer>C3</answer>");
  } else if (lateNDVI > earlyNDVI) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
